mapper.select:
SELECT id, vessel_id, period_year, period_month, crew_count, illness_count,
       injury_count, evacuation_count, sick_leave_days, pos_sm_synced_at,
       excel_upload_id, uploaded_by, comment, created_at, updated_at, deleted
  FROM tb_safety_performance_sea
 WHERE vessel_id = #{vesselId}
   AND period_year = #{periodYear}
   AND period_month = #{periodMonth}
   AND deleted = 0
